/**
 * The introduction's anonymous counter (the data plan, owner 22 Oct 2026):
 * each screen of the introduction is counted once per install, so the
 * operators can see which screen visitors stop at. The request carries the
 * screen's name and the app's platform and nothing else: no account, no id,
 * no answer. It is sent once and never retried; a failure, or a server
 * without the endpoint, changes nothing for the visitor.
 *
 * Which screens were sent lives in the small preferences store beside
 * `wb.intro`, so a reload or a second visit does not count them again.
 */
import { me } from '@/api/endpoints.js';
import type { ApiIntroStepInput } from '@/api/types.js';
import { platform } from '@/lib/platform/index.js';

/**
 * Screens added after the contract's list (sales plan G, 23 Oct 2026): the
 * reminder question and the goal. The server refuses a step it does not
 * know (400) until `IntroStepInput.step` lists them, so these are noted as
 * sent only once the server has taken them: they start counting the day the
 * server does, with no app update. When the contract gains them, move them
 * into `ApiIntroStepInput['step']` and drop this list.
 */
export const NEWER_STEPS = ['remind', 'goal'] as const;
type NewerStep = (typeof NEWER_STEPS)[number];

export type IntroStep = ApiIntroStepInput['step'] | NewerStep;

const KEY = 'wb.introSteps';

function sentSteps(): string[] {
  return (platform.prefs.get(KEY) ?? '').split(',').filter((s) => s !== '');
}

function noteSent(step: IntroStep): void {
  const sent = sentSteps();
  if (!sent.includes(step)) platform.prefs.set(KEY, [...sent, step].join(','));
}

function isNewer(step: IntroStep): step is NewerStep {
  return (NEWER_STEPS as readonly string[]).includes(step);
}

/** Steps on their way to a server that may refuse them, so a quick re-render does not send twice. */
const inFlight = new Set<IntroStep>();

export function countIntroStep(step: IntroStep): void {
  try {
    if (sentSteps().includes(step) || inFlight.has(step)) return;
    if (!isNewer(step)) {
      noteSent(step);
      void me.countIntroStep({ step, platform: platform.env.platform }).catch(() => undefined);
      return;
    }
    inFlight.add(step);
    // The generated type does not list the newer steps yet; the server judges them.
    const body = { step, platform: platform.env.platform } as unknown as ApiIntroStepInput;
    void me
      .countIntroStep(body)
      .then(() => {
        noteSent(step);
      })
      .catch(() => undefined)
      .finally(() => {
        inFlight.delete(step);
      });
  } catch {
    // A counter is never worth an error on the introduction.
  }
}
